<?php require __DIR__.'/../src/bootstrap.php'; $s=storage();$settings=(new SignalPilot\Services\AppService($s))->settings();foreach($s->all('email_queue') as $m){if(($m['status']??'')!=='queued')continue;$p=$m['payload'];$approve=app_url('opportunity.php?do=approve&id='.$p['id']);$deny=app_url('opportunity.php?do=deny&id='.$p['id']);$body='<h2>SignalPilot Opportunity Detected</h2><p>Symbol: '.$p['symbol'].'<br>Current Price: '.$p['current_price'].'<br>Suggested Entry: '.$p['entry'].'<br>Suggested Stop Loss: '.$p['stop_loss'].'<br>Suggested Take Profit: '.$p['take_profit'].'<br>Reward/Risk: '.$p['reward_risk'].'<br>Confidence: '.$p['confidence'].'%<br>Reasoning: '.htmlspecialchars($p['reason']).'</p><p><a href="'.$approve.'">APPROVE TRADE</a> &nbsp; <a href="'.$deny.'">DENY TRADE</a></p>'; if(class_exists('PHPMailer\\PHPMailer\\PHPMailer')&&($settings['smtp_host']??'')){ $mail=new PHPMailer\PHPMailer\PHPMailer(true);$mail->isSMTP();$mail->Host=$settings['smtp_host'];$mail->Port=(int)$settings['smtp_port'];$mail->Username=$settings['smtp_user'];$mail->Password=$settings['smtp_pass'];$mail->SMTPSecure=$settings['smtp_secure'];$mail->SMTPAuth=(bool)$mail->Username;$mail->setFrom($settings['smtp_user']?:'noreply@localhost','SignalPilot');$mail->addAddress($m['to']);$mail->isHTML(true);$mail->Subject='SignalPilot Opportunity Detected';$mail->Body=$body;$mail->send(); } file_put_contents(SP_ROOT.'/storage/logs/email.log',date('c').' '.$m['to'].' '.$body."\n",FILE_APPEND);$s->update('email_queue',$m['id'],['status'=>'sent','sent_at'=>date('c')]);}
